//! The "Command flags" section of docs/reference.md, generated from the
//! CLI's own definition so the page can't drift from `--help` (#689).
//! The test fails when the page differs; to rewrite the section:
//!
//! ```sh
//! UPDATE_REFERENCE=1 cargo test -p ganymede-cli --bin ganymede reference
//! ```

use clap::{ArgAction, Command, CommandFactory};

const START: &str =
    "<!-- command-flags:start (generated by crates/ganymede-cli/src/reference.rs) -->";
const END: &str = "<!-- command-flags:end -->";

/// Clap hasn't propagated global flags yet, so a command lists only the
/// ones it declares; the root's are the "Flags for every command" table.
///
/// Commands whose flags the page lists elsewhere: the global flags and
/// "Server flags" tables.
const SERVER: &str = "serve";

/// Table cell text: one line, with `|` escaped.
fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}

/// The flag as `--help` shows it: `-o`, `--output <PATH>`.
fn flag(arg: &clap::Arg) -> String {
    let mut names = vec![];
    if let Some(short) = arg.get_short() {
        names.push(format!("`-{short}`"));
    }
    // A value that may be left out shows as `[<NAME>]`, as in `--help`.
    let optional = arg.get_num_args().is_some_and(|n| n.min_values() == 0);
    let value = match arg.get_action() {
        ArgAction::Set | ArgAction::Append => {
            let names = arg
                .get_value_names()
                .map(|v| {
                    v.iter()
                        .map(|n| format!("<{n}>"))
                        .collect::<Vec<_>>()
                        .join(" ")
                })
                .unwrap_or_else(|| format!("<{}>", arg.get_id().as_str().to_uppercase()));
            if optional {
                format!(" [{names}]")
            } else {
                format!(" {names}")
            }
        }
        _ => String::new(),
    };
    names.push(format!("`--{}{value}`", arg.get_long().unwrap_or_default()));
    names.join(", ")
}

/// What the flag does: its help text, and its default when it has one.
fn effect(arg: &clap::Arg) -> String {
    let text = arg.get_help().map(|h| h.to_string()).unwrap_or_default();
    let defaults: Vec<_> = arg
        .get_default_values()
        .iter()
        .map(|v| v.to_string_lossy().into_owned())
        .collect();
    let shows_default = matches!(arg.get_action(), ArgAction::Set | ArgAction::Append);
    let text = text.trim_end().trim_end_matches('.');
    let text = if shows_default && !defaults.is_empty() && !text.contains("efault") {
        format!("{text}. Default `{}`.", defaults.join(" "))
    } else if text.is_empty() {
        String::new()
    } else {
        format!("{text}.")
    };
    cell(&text)
}

/// Commands that take every `serve` flag.
fn flattens_server(path: &str) -> bool {
    path == "lab" || path == "ui"
}

fn walk(cmd: &Command, path: &str, server: &[String], out: &mut String) {
    let flags: Vec<_> = cmd
        .get_arguments()
        .filter(|a| !a.is_hide_set() && a.get_long().is_some())
        // clap's own --help and --version, not a command's `--version <V>`.
        .filter(|a| !matches!(a.get_action(), ArgAction::Help | ArgAction::Version))
        // lab and ui take serve's flags, which the "Server flags" table lists.
        .filter(|a| {
            !(flattens_server(path) && server.iter().any(|s| Some(s.as_str()) == a.get_long()))
        })
        .collect();
    if !path.is_empty() && path != SERVER && !flags.is_empty() {
        out.push_str(&format!(
            "\n### `{path}`\n\n| Flag | Effect |\n| --- | --- |\n"
        ));
        for arg in flags {
            out.push_str(&format!("| {} | {} |\n", flag(arg), effect(arg)));
        }
        if flattens_server(path) {
            out.push_str("\nAnd the [server flags](#server-flags).\n");
        }
    }
    for sub in cmd.get_subcommands() {
        if sub.is_hide_set() || sub.get_name() == "help" {
            continue;
        }
        let p = if path.is_empty() {
            sub.get_name().to_string()
        } else {
            format!("{path} {}", sub.get_name())
        };
        walk(sub, &p, server, out);
    }
}

/// The section's Markdown, between its markers.
fn section() -> String {
    let cli = crate::Cli::command();
    let server: Vec<String> = cli
        .find_subcommand(SERVER)
        .expect("serve")
        .get_arguments()
        .filter_map(|a| a.get_long().map(str::to_string))
        .collect();
    let mut out = String::new();
    walk(&cli, "", &server, &mut out);
    format!("{START}\n{out}\n{END}")
}

#[test]
fn reference_lists_every_command_flag() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/reference.md");
    let doc = std::fs::read_to_string(path).unwrap();
    let (start, end) = (
        doc.find(START).expect("start marker"),
        doc.find(END).expect("end marker"),
    );
    let current = &doc[start..end + END.len()];
    let generated = section();
    if current != generated {
        if std::env::var_os("UPDATE_REFERENCE").is_some() {
            std::fs::write(path, doc.replace(current, &generated)).unwrap();
            return;
        }
        panic!(
            "docs/reference.md's command flags differ from the CLI. Rewrite them with\n  \
             UPDATE_REFERENCE=1 cargo test -p ganymede-cli --bin ganymede reference"
        );
    }
}
